contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: amount to deposit first, then amount to attempt to collect
    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "need balance for deposit");

        // Deposit some funds so there is a possibility for Collect to transfer out
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Observe contract balance before Collect
        uint beforeEth = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterEth = address(c).balance;

        // General rule: Collect cannot increase c's ETH balance
        assert(afterEth <= beforeEth);
    }

    receive() external payable {}
}

